template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{90} \def\angleb{210} \def\anglec{330} \def\showcenter{1} \def\showtriangle{1} \def\showdiameter{0} \def\diameterlabel{D} \def\showinscribedangle{0} \def\showcentralangle{0} \def\showchordmidpoint{0} \def\chordmidlabel{M} \def\labela{A} \def\labelb{B} \def\labelc{C}
% 视觉归一化：把外接圆直径缩放到 6cm，保证图形视觉大小稳定。
\pgfmathsetmacro{\figscale}{3 / \radius}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\Ax}{\radius*cos(\anglea)}
\pgfmathsetmacro{\Ay}{\radius*sin(\anglea)}
\pgfmathsetmacro{\Bx}{\radius*cos(\angleb)}
\pgfmathsetmacro{\By}{\radius*sin(\angleb)}
\pgfmathsetmacro{\Cx}{\radius*cos(\anglec)}
\pgfmathsetmacro{\Cy}{\radius*sin(\anglec)}
% 弦 BC 的中点
\pgfmathsetmacro{\Mx}{(\Bx + \Cx)/2}
\pgfmathsetmacro{\My}{(\By + \Cy)/2}
% A 的对径点（直径 A--对径点）
\pgfmathsetmacro{\Dx}{-\Ax}
\pgfmathsetmacro{\Dy}{-\Ay}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (A) at (\Ax,\Ay);
  \coordinate (B) at (\Bx,\By);
  \coordinate (C) at (\Cx,\Cy);
  \coordinate (D) at (\Dx,\Dy);
  \coordinate (M) at (\Mx,\My);
  % 外接圆
  \draw[thick] (O) circle [radius=\radius];
  % 内接三角形（三边即三条弦）
  \ifnum\showtriangle>0
    \draw[thick] (A) -- (B) -- (C) -- cycle;
  \fi
  % 过顶点 A 的直径
  \ifnum\showdiameter>0
    \draw[thick] (A) -- (D);
    \fill (D) circle [radius=\dotr pt];
    \node at ({1.16*\Dx},{1.16*\Dy}) {$\diameterlabel$};
  \fi
  % 圆心角 ∠AOB：画半径 OA、OB 并标角弧（取小于 180° 的一侧）
  \ifnum\showcentralangle>0
    \draw[thick] (O) -- (A);
    \draw[thick] (O) -- (B);
    \pgfmathsetmacro{\sang}{atan2(\Ay,\Ax)}
    \pgfmathsetmacro{\eraw}{atan2(\By,\Bx)}
    \pgfmathsetmacro{\edif}{\eraw - \sang}
    \pgfmathsetmacro{\eang}{\sang + \edif - 360*round(\edif/360)}
    \pgfmathsetmacro{\arcr}{min(0.5/\figscale, \radius*0.32)}
    \draw[thick] ({\arcr*cos(\sang)},{\arcr*sin(\sang)}) arc[start angle=\sang, end angle=\eang, radius=\arcr];
  \fi
  % 圆周角 ∠ACB 的角弧（顶点 C，夹在 CA、CB 之间）
  \ifnum\showinscribedangle>0
    \ifnum\showtriangle>0
      \pgfmathsetmacro{\vax}{\Ax-\Cx}
      \pgfmathsetmacro{\vay}{\Ay-\Cy}
      \pgfmathsetmacro{\vbx}{\Bx-\Cx}
      \pgfmathsetmacro{\vby}{\By-\Cy}
      \pgfmathsetmacro{\valen}{sqrt(\vax*\vax+\vay*\vay)}
      \pgfmathsetmacro{\vblen}{sqrt(\vbx*\vbx+\vby*\vby)}
      \pgfmathsetmacro{\sang}{atan2(\vay,\vax)}
      \pgfmathsetmacro{\eraw}{atan2(\vby,\vbx)}
      \pgfmathsetmacro{\edif}{\eraw - \sang}
      \pgfmathsetmacro{\eang}{\sang + \edif - 360*round(\edif/360)}
      \pgfmathsetmacro{\arcr}{min(0.4/\figscale, \valen*0.28, \vblen*0.28)}
      \draw[thick] ({\Cx+\arcr*cos(\sang)},{\Cy+\arcr*sin(\sang)}) arc[start angle=\sang, end angle=\eang, radius=\arcr];
    \fi
  \fi
  % 外心 O
  \ifnum\showcenter>0
    \fill (O) circle [radius=\dotr pt];
    \node[below left=3pt] at (O) {$O$};
  \fi
  % 弦 BC 的中点
  \ifnum\showchordmidpoint>0
    \fill (M) circle [radius=\dotr pt];
    \node at ({1.14*\Mx},{1.14*\My}) {$\chordmidlabel$};
  \fi
  % 顶点（标签沿径向外移，避免压在圆上）
  \fill (A) circle [radius=\dotr pt];
  \fill (B) circle [radius=\dotr pt];
  \fill (C) circle [radius=\dotr pt];
  \node at ({1.16*\Ax},{1.16*\Ay}) {$\labela$};
  \node at ({1.16*\Bx},{1.16*\By}) {$\labelb$};
  \node at ({1.16*\Cx},{1.16*\Cy}) {$\labelc$};
\end{tikzpicture}
